import type { ExtractedPlan, PriorityLevel, QuadrantItem, ScheduleBlock, TaskItem } from '../types';

/**
 * Parses markdown text generated by Aurelia AI and extracts structured
 * tasks, schedules, and priority quadrants.
 */
export function parsePlanFromMarkdown(markdown: string, planTitle?: string): ExtractedPlan {
  const lines = markdown.split('\n');
  const tasks: TaskItem[] = [];
  const schedule: ScheduleBlock[] = [];
  const quadrants: QuadrantItem[] = [];

  // Patterns
  const timeRangeRegex = /(?:(\d{1,2}(?::\d{2})?\s*(?:AM|PM|am|pm)?)\s*(?:-|–|to)\s*(\d{1,2}(?::\d{2})?\s*(?:AM|PM|am|pm)?))/i;
  const singleTimeRegex = /(?:^|\s)(?:at\s+)?(\d{1,2}:\d{2}\s*(?:AM|PM|am|pm)?)(?::|\s)/i;
  const bulletRegex = /^[\s]*[-*+]\s+(.*)$/;
  const numberedRegex = /^[\s]*\d+[\.\)]\s+(.*)$/;
  const checklistRegex = /^[\s]*[-*+]\s+\[([ xX])\]\s+(.*)$/;

  let currentHeading = '';

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const trimmed = rawLine.trim();
    if (!trimmed) continue;

    // Track heading
    if (trimmed.startsWith('#')) {
      currentHeading = trimmed.replace(/^#+\s*/, '');
      continue;
    }

    // Check for checklist items
    const checkMatch = trimmed.match(checklistRegex);
    if (checkMatch) {
      const isCompleted = checkMatch[1].toLowerCase() === 'x';
      const cleanText = cleanMarkdown(checkMatch[2]);
      if (cleanText.length > 2) {
        tasks.push({
          id: `task-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          text: cleanText,
          completed: isCompleted,
          priority: inferPriority(cleanText, currentHeading),
          category: currentHeading || undefined,
        });
      }
      continue;
    }

    // Check for schedule / time block
    const timeRangeMatch = trimmed.match(timeRangeRegex);
    const singleTimeMatch = trimmed.match(singleTimeRegex);

    if (timeRangeMatch || (singleTimeMatch && trimmed.length < 120)) {
      const timeStr = timeRangeMatch ? timeRangeMatch[0] : singleTimeMatch![1];
      const details = cleanMarkdown(trimmed.replace(timeStr, '').replace(/^[:\s\-–]+/, ''));
      if (details.length > 2) {
        schedule.push({
          id: `sched-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          time: timeStr.trim(),
          title: details.split(/[:\-\(]/)[0]?.trim() || details,
          details: details,
          category: inferCategory(details),
        });
      }
    }

    // Check for regular bullet points or numbered lists
    const bulletMatch = trimmed.match(bulletRegex);
    const numMatch = trimmed.match(numberedRegex);
    const contentMatch = bulletMatch || numMatch;

    if (contentMatch) {
      const text = cleanMarkdown(contentMatch[1]);
      if (text.length > 3 && !text.toLowerCase().includes('http') && tasks.length < 30) {
        // Classify into Eisenhower quadrant if relevant
        const headingLower = currentHeading.toLowerCase();
        const textLower = text.toLowerCase();

        if (
          headingLower.includes('urgent') ||
          headingLower.includes('do first') ||
          textLower.includes('high priority') ||
          textLower.includes('urgent')
        ) {
          quadrants.push({
            id: `quad-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            text,
            quadrant: 'do',
          });
        } else if (
          headingLower.includes('schedule') ||
          headingLower.includes('plan') ||
          textLower.includes('important')
        ) {
          quadrants.push({
            id: `quad-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            text,
            quadrant: 'schedule',
          });
        } else if (headingLower.includes('delegate') || textLower.includes('delegate')) {
          quadrants.push({
            id: `quad-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            text,
            quadrant: 'delegate',
          });
        } else if (headingLower.includes('eliminate') || headingLower.includes('drop')) {
          quadrants.push({
            id: `quad-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            text,
            quadrant: 'eliminate',
          });
        }

        // Also add as actionable task if not already duplicate
        if (!tasks.some((t) => t.text.toLowerCase() === text.toLowerCase())) {
          tasks.push({
            id: `task-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            text,
            completed: false,
            priority: inferPriority(text, currentHeading),
            category: currentHeading || undefined,
          });
        }
      }
    }
  }

  // Determine a title
  const finalTitle =
    planTitle ||
    lines.find((l) => l.trim().startsWith('#'))?.replace(/^#+\s*/, '') ||
    'Custom Aurelia Plan';

  return {
    id: `plan-${Date.now()}`,
    title: cleanMarkdown(finalTitle),
    extractedAt: Date.now(),
    rawMarkdown: markdown,
    tasks: tasks.slice(0, 25),
    schedule: schedule.slice(0, 20),
    quadrants: quadrants.slice(0, 20),
  };
}

function cleanMarkdown(str: string): string {
  return str
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^[:\s\-•]+/, '')
    .trim();
}

function inferPriority(text: string, context: string): PriorityLevel {
  const combined = (text + ' ' + context).toLowerCase();
  if (
    combined.includes('urgent') ||
    combined.includes('high') ||
    combined.includes('critical') ||
    combined.includes('asap') ||
    combined.includes('p0') ||
    combined.includes('priority 1')
  ) {
    return 'high';
  }
  if (
    combined.includes('low') ||
    combined.includes('optional') ||
    combined.includes('someday') ||
    combined.includes('later') ||
    combined.includes('p2')
  ) {
    return 'low';
  }
  return 'medium';
}

function inferCategory(text: string): ScheduleBlock['category'] {
  const lower = text.toLowerCase();
  if (lower.includes('break') || lower.includes('lunch') || lower.includes('walk') || lower.includes('rest')) {
    return 'break';
  }
  if (lower.includes('review') || lower.includes('debrief') || lower.includes('reflect')) {
    return 'review';
  }
  if (lower.includes('email') || lower.includes('admin') || lower.includes('prep') || lower.includes('organize')) {
    return 'admin';
  }
  return 'focus';
}
